    const objects = objectsMember(body, "items");
    if (objects === null)
        return null;
    const items = [];
    for (const each of objects) {
        const mapped = one(each);
        if (mapped === null)
            return null;
        items.push(mapped);
    }
    return { items, nextCursor: textMember(body, "nextCursor") };
